using System;
using System.Drawing;
using System.IO;
using System.Windows.Forms;
namespace MadCardMaker;
public static class MakerHelp
{
 public static void Open(IWin32Window owner){using(var f=new Form{Text="MadCard Maker — getting started",Size=new Size(780,650),StartPosition=FormStartPosition.CenterParent}){
 var text=new TextBox{Dock=DockStyle.Fill,ReadOnly=true,Multiline=true,ScrollBars=ScrollBars.Vertical,Text="MADCard Maker REVANCED\r\n\r\n1. Create a mod, or select an existing mod and choose Open / edit.\r\n2. Add a deck to organize your cards. Select that deck before creating a card.\r\n3. Choose a card type and an inherited root. Edit fields on the left; the right panel explains the selected field and suggests references.\r\n4. Save to deck applies your card to the selected deck. Save decks writes your mod's deck files. Export deck writes a typed MadCard deck JSON for a mod folder.\r\n\r\nStarter presets: choose from 12 editable drafts. Duplicate card makes an independent copy. Project notebook stores ideas, tasks and card notes outside game decks.\r\n\r\nReview: check a card, import a single card or deck, and inspect Overrides, Resolved, Deck JSON and Changes tabs. Ctrl+Shift+V checks the current card.\r\n\r\nSearch: Ctrl+F finds fields/cards without changing your deck's order. Enter moves to the next match. Double-click a card to edit it.\r\n\r\nReferences: typing filters choices. Explicitly choose a value to accept its ID. Invalid numbers leave the previous value intact. Ctrl+Z / Ctrl+Y undo and redo card edits.\r\n\r\nFile types: MadCard decks use typed arrays of sparse overrides, with Filename and Root references. This is the original MadCard format, separate from NEM's loose Custom Stuff JSON.\r\n\r\nBackups: deck/JSON overwrites retain a .bak copy. Check a mod's enabled status and load order before using it in game.\r\n\r\nOriginal MadCard Maker code, database, documentation and icon remain credited to their original creators. This is a community interface rewrite; it does not claim authorship of the original tool."};f.Controls.Add(text);f.Padding=new Padding(20);DossierStyle.Apply(f);f.ShowDialog(owner);}}
 public static void Interface(IWin32Window owner){using(var f=new Form{Text="Appearance and feedback",Size=new Size(600,610),MinimumSize=new Size(540,540),StartPosition=FormStartPosition.CenterParent}){
 var root=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(20)};
 var palettes=new ComboBox{Width=480,DropDownStyle=ComboBoxStyle.DropDownList};palettes.Items.AddRange(new object[]{"Keep current colors","REVANCED red","Graphite","Olive"});palettes.SelectedIndex=0;
 var fonts=new ComboBox{Width=480,DropDownStyle=ComboBoxStyle.DropDownList};fonts.Items.Add("Play");foreach(var font in System.Drawing.FontFamily.Families)if(!fonts.Items.Contains(font.Name))fonts.Items.Add(font.Name);fonts.SelectedItem=DossierTheme.Load().FontFamily;if(fonts.SelectedIndex<0)fonts.SelectedIndex=0;
 var sizing=new ComboBox{Width=480,DropDownStyle=ComboBoxStyle.DropDownList};sizing.Items.AddRange(new object[]{"Compact · 100%","Comfortable · 115%","Large · 130%"});sizing.SelectedIndex=DossierTheme.Load().InterfaceScale>=1.25f?2:DossierTheme.Load().InterfaceScale>1.05f?1:0;
 var audio=new CheckBox{Text="Quiet click sounds",Checked=DossierPreferences.Current.Sounds,AutoSize=true};var typing=new CheckBox{Text="Typing sounds",Checked=DossierPreferences.Current.TypingSounds,AutoSize=true};var motion=new CheckBox{Text="Smooth interface animations",Checked=DossierPreferences.Current.Animations,AutoSize=true};
 var volume=new TrackBar{Width=480,Minimum=0,Maximum=30,TickFrequency=5,Value=(int)Math.Round(Math.Min(.30,DossierPreferences.Current.Volume)*100)};var level=new Label{Text="Feedback volume: "+volume.Value+"%",AutoSize=true};volume.ValueChanged+=(_,__)=>level.Text="Feedback volume: "+volume.Value+"%";
 var button=new DossierButton{Text="Save appearance",Width=480,Height=40};root.Controls.Add(new Label{Text="Color palette",AutoSize=true});root.Controls.Add(palettes);root.Controls.Add(new Label{Text="Interface font · Play is bundled",AutoSize=true});root.Controls.Add(fonts);root.Controls.Add(new Label{Text="Text and control size",AutoSize=true});root.Controls.Add(sizing);root.Controls.Add(audio);root.Controls.Add(typing);root.Controls.Add(motion);root.Controls.Add(level);root.Controls.Add(volume);root.Controls.Add(new Label{Text="Reopen the app to apply size, fonts and colors. Sound changes apply now.\r\nYour cards and decks are unaffected.",Width=480,Height=60});root.Controls.Add(button);f.Controls.Add(root);DossierStyle.Apply(f);
 button.Click+=(_,__)=>{try{var theme=DossierTheme.Load();theme.FontFamily=theme.HeadingFont=fonts.Text;if(palettes.SelectedIndex==1){theme=new DossierTheme{FontFamily=fonts.Text,HeadingFont=fonts.Text};}else if(palettes.SelectedIndex==2){theme.Background="#17191C";theme.Surface="#22252A";theme.Input="#101216";theme.Accent="#AABED3";theme.Line="#3A414B";}else if(palettes.SelectedIndex==3){theme.Background="#181B17";theme.Surface="#242922";theme.Input="#10140F";theme.Accent="#B2C58E";theme.Line="#414B37";}theme.InterfaceScale=new[]{1f,1.15f,1.3f}[sizing.SelectedIndex];theme.Write(DossierTheme.ThemePath);var p=DossierPreferences.Current;p.Sounds=audio.Checked;p.TypingSounds=typing.Checked;p.Animations=motion.Checked;p.Volume=volume.Value/100d;p.QuietFeedbackVersion=1;p.Persist();f.Close();}catch(Exception ex){DossierDialog.Show(f,ex.Message);}};f.ShowDialog(owner);}}
 public static void Write(string path,string text){path=Path.GetFullPath(path);Directory.CreateDirectory(Path.GetDirectoryName(path));var temporary=path+".tmp";File.WriteAllText(temporary,text);if(File.Exists(path))File.Replace(temporary,path,path+".bak");else File.Move(temporary,path);}
}
